package ociresources

import (
	"errors"
	tea "github.com/charmbracelet/bubbletea"
	"strings"
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// DEVDESK-146 step 3: a scan or pull failure of an image comes from the
// router's memory (m.failures) and from nowhere else. The Scanned cell no
// longer has an error branch, and a successful removal tells the router to
// forget the tag.

// A failed ImageScanFinishedMsg alone leaves no trace in the view: without the
// router's snapshot the row neither fails nor loses its last date.
func TestAScanFinishedWithAnErrorSetsNoLocalFailure(t *testing.T) {
	m := loadedModel(t)
	before := scannedCell(imageRowByName(t, m, imgRef))
	m = feed(t, m, ImageScanFinishedMsg{ImageName: imgRef, Err: errors.New("trivy: exit status 1")})

	row := imageRowByName(t, m, imgRef)
	if got := m.rowActivity(row).State; got == indicator.Failed {
		t.Errorf("the row failed with nothing in the router's memory: %v", got)
	}
	if got := scannedCell(row); got != before || strings.Contains(got, "error") {
		t.Errorf("Scanned cell = %q after a failed scan, want the last date %q", got, before)
	}
}

// With the failure in the snapshot the dot is red and the Scanned cell still
// reads the last successful date.
func TestAFailedImageKeepsItsLastScanDate(t *testing.T) {
	f := []jobs.Failure{ociFailure(jobs.KindScan, ociCtx, imgRef, time.Now())}
	m := ociSnapshot(t, ociCtx, nil, f)
	row := imageRowByName(t, m, imgRef)

	if got := row.Activity.State; got != indicator.Failed {
		t.Fatalf("activity = %v, want Failed", got)
	}
	got := scannedCell(row)
	if strings.Contains(got, "error") || got != timeAgo(row.Entry.ScannedAt) {
		t.Errorf("Scanned cell = %q, want %q", got, timeAgo(row.Entry.ScannedAt))
	}
	if style := scannedStyle(row); style.GetForeground() == theme.StatusErrorStyle.GetForeground() {
		t.Errorf("Scanned cell still painted as an error")
	}
}

func TestScannedCellHasNoErrorBranch(t *testing.T) {
	at := time.Now().Add(-2 * time.Hour)
	row := imageRow{Scanned: true, Entry: scanCacheFixture()[imgRef]}
	row.Entry.ScannedAt = at
	row.Activity.State = indicator.Failed
	if got := scannedCell(row); got != timeAgo(at) {
		t.Errorf("scannedCell = %q, want %q", got, timeAgo(at))
	}
	row.Scanned = false
	if got := scannedCell(row); got != "-" {
		t.Errorf("unscanned failed row = %q, want -", got)
	}
}

func forgotten(msgs []tea.Msg) []jobs.ForgetTargetMsg {
	var out []jobs.ForgetTargetMsg
	for _, msg := range msgs {
		if f, ok := msg.(jobs.ForgetTargetMsg); ok {
			out = append(out, f)
		}
	}
	return out
}

// A removal that succeeded asks the router to forget the row's raw tag, once.
func TestASuccessfulRemovalForgetsTheTag(t *testing.T) {
	t.Setenv("PATH", t.TempDir()) // the reload that follows must not reach docker
	m := loadedModel(t)
	img := imageRowByName(t, m, imgRef)

	_, cmd := step(t, m, ImageActionMsg{Action: "remove", ID: img.Image.ID, Name: img.RawName})
	got := forgotten(testutil.Msgs(cmd))
	if len(got) != 1 || got[0].Target != imgRef {
		t.Errorf("forget messages = %+v, want one for %q", got, imgRef)
	}
}

// A failed removal keeps the memory and says why at the footer.
func TestAFailedRemovalDoesNotForgetTheTag(t *testing.T) {
	t.Setenv("PATH", t.TempDir())
	m := loadedModel(t)
	img := imageRowByName(t, m, imgRef)

	m, cmd := step(t, m, ImageActionMsg{Action: "remove", ID: img.Image.ID, Name: img.RawName, Err: errors.New("in use")})
	if got := forgotten(testutil.Msgs(cmd)); len(got) != 0 {
		t.Errorf("a failed removal asked to forget: %+v", got)
	}
	if !m.footer.IsSet() {
		t.Error("the removal error is not at the footer")
	}
}
package app

import (
	"errors"
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-146 step 3: the OCI Images table takes scan and pull failures from
// jobs.Registry, so they follow the image across views, reloads and rebuilds.

const ociOther = "redis:7"

// ociRouter is the :sec router (which holds nginx:1.27 in its inventory) with
// the OCI view built and listing nginx:1.27 and redis:7.
func ociRouter(t *testing.T) *App {
	t.Helper()
	t.Setenv("PATH", t.TempDir()) // no docker: a reload command must stay inert
	a, _ := secRouter(t, 180)
	openOCI(t, a)
	return a
}

func openOCI(t *testing.T, a *App) {
	t.Helper()
	_ = a.switchView(command.ViewOCIResources)
	a.Update(ociresources.ImagesListMsg{Images: []docker.Image{
		{ID: "aaa1111", Repository: "nginx", Tag: "1.27"},
		{ID: "bbb2222", Repository: "redis", Tag: "7"},
	}})
	a.resize(a.width, a.height)
}

func ociScreen(a *App) string { return ansi.Strip(a.views[command.ViewOCIResources].View()) }

func ociWantFailed(t *testing.T, a *App, name string) {
	t.Helper()
	if row := rowOf(t, ociScreen(a), name); !strings.Contains(row, failedGlyph()) {
		t.Errorf("OCI row %q has no %s: %q", name, failedGlyph(), row)
	}
}

func ociWantNotFailed(t *testing.T, a *App, name string) {
	t.Helper()
	if row := rowOf(t, ociScreen(a), name); strings.Contains(row, failedGlyph()) {
		t.Errorf("OCI row %q shows %s: %q", name, failedGlyph(), row)
	}
}

// failScanFromSec poses a scan failure the way :sec reports one for an image.
func failScanFromSec(a *App, image string) {
	a.Update(jobs.StartMsg{Run: jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "inventory", image)})
	a.Update(ociresources.ImageScanFinishedMsg{ImageName: image, Err: errors.New("boom")})
}

func failPull(a *App, image string) {
	a.Update(jobs.StartMsg{Run: jobs.NewRun(jobs.KindPull, command.ViewOCIResources, "", "images", image)})
	a.Update(ociresources.RegistryPullCompleteMsg{ImageName: image, Err: errors.New("boom")})
}

func TestOCIShowsAScanFailedFromSec(t *testing.T) {
	a := ociRouter(t)
	failScanFromSec(a, secImage)
	ociWantFailed(t, a, secImage)
	ociWantNotFailed(t, a, ociOther)
}

func TestOCIRetryClearsTheFailure(t *testing.T) {
	a := ociRouter(t)
	failScanFromSec(a, secImage)
	ociWantFailed(t, a, secImage)

	a.Update(jobs.StartMsg{Run: jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", secImage)})
	row := rowOf(t, ociScreen(a), secImage)
	if strings.Contains(row, failedGlyph()) {
		t.Errorf("a retry in flight still shows %s: %q", failedGlyph(), row)
	}
	if !strings.Contains(row, indicator.Glyph(indicator.Queued, true)) {
		t.Errorf("a retry waiting to start has no queued dot: %q", row)
	}
}

func TestOCIFailureSurvivesRefreshAndARebuiltView(t *testing.T) {
	a := ociRouter(t)
	failScanFromSec(a, secImage)

	a.Update(testutil.Key("ctrl+r")) // the reload command is not run: no docker
	ociWantFailed(t, a, secImage)

	delete(a.views, command.ViewOCIResources)
	openOCI(t, a)
	ociWantFailed(t, a, secImage)
}

func TestOCIFailureIsFilteredByContext(t *testing.T) {
	a := ociRouter(t)
	failScanFromSec(a, secImage)

	a.currentContext = "other"
	delete(a.views, command.ViewOCIResources)
	openOCI(t, a)
	ociWantNotFailed(t, a, secImage)

	a.currentContext = "default"
	delete(a.views, command.ViewOCIResources)
	openOCI(t, a)
	ociWantFailed(t, a, secImage)
}

// D5: :sec shows scan failures only, OCI shows scan and pull.
func TestOCIShowsAPullFailureThatSecDoesNot(t *testing.T) {
	a := ociRouter(t)
	failPull(a, secImage)
	ociWantFailed(t, a, secImage)

	openSec(t, a)
	wantNotFailed(t, a, secImage)
}

// A removal that succeeded drops the failure; one that failed keeps it.
func TestOCISuccessfulRemovalClearsTheFailure(t *testing.T) {
	a := ociRouter(t)
	failScanFromSec(a, secImage)

	_, cmd := a.Update(ociresources.ImageActionMsg{Action: "remove", ID: "aaa1111", Name: secImage, Err: errors.New("in use")})
	for _, msg := range testutil.Msgs(cmd) {
		a.Update(msg)
	}
	if !remembered(a, jobs.KindScan, secImage, "default") {
		t.Fatal("a refused removal dropped the failure")
	}

	_, cmd = a.Update(ociresources.ImageActionMsg{Action: "remove", ID: "aaa1111", Name: secImage})
	for _, msg := range testutil.Msgs(cmd) {
		a.Update(msg)
	}
	if remembered(a, jobs.KindScan, secImage, "default") {
		t.Error("the failure survived the removal of the image")
	}
	ociWantNotFailed(t, a, secImage)
}

